    if (srst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      empty <= 1;
      full <= 0;
    end else begin
      if (wr_en && !full) begin
        ram[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        count <= count + 1;
        empty <= 0;
        if (count == 16) full <= 1;
