module top_module( g, p, g_prec, p_prec, g_out, p_out );input g, p, g_prec, p_prec;
  output g_out, p_out;
  wire   n5, p_prec_inv;

  // Inverting p_prec
  assign p_prec_inv = ~p_prec;

  // AND-OR-INVERT gate
  assign n5 = p_prec_inv & g_prec;
  assign g_out = p | n5;
  assign g_out = ~n5; // Overwriting previous g_out assignment

  // AND gate
  assign p_out = p & p_prec;
endmodule

