description:
Design a combinational logic circuit that implements a 4-variable Karnaugh map. The module takes four binary inputs (A, B, C, D) and produces a single binary output (F) based on the defined logic combinations corresponding to the values of these inputs, effectively simplifying boolean expressions through visual grouping of terms. The output F varies depending on the selected combinations of A, B while being conditioned on C, D, supporting the inherent mapping characteristics of a Karnaugh map for optimization.
module top_module(
  input wire A, B, C, D,
  output reg F
);

code:
module top_module(
  input wire A, B, C, D,
  output reg F
);always @(*) begin
    case ({A,B})
      2'b00: begin
        case ({C,D})
          2'b00: F = 1'b0;
          2'b01: F = 1'b1;
          2'b11: F = 1'b1;
          2'b10: F = 1'b0;
        endcase
      end
      2'b01: begin
        case ({C,D})
          2'b00: F = 1'b1;
          2'b01: F = 1'b0;
          2'b11: F = 1'b0;
          2'b10: F = 1'b1;
        endcase
      end
      2'b11: begin
        case ({C,D})
          2'b00: F = 1'b1;
          2'b01: F = 1'b0;
          2'b11: F = 1'b0;
          2'b10: F = 1'b1;
        endcase
      end
      2'b10: begin
        case ({C,D})
          2'b00: F = 1'b0;
          2'b01: F = 1'b1;
          2'b11: F = 1'b1;
          2'b10: F = 1'b0;
        endcase
      end
    endcase
  end

endmodule

