module up_down_counter(
    input clk,
    input rst_n,
    input up,
    output reg [3:0] count
);
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 4'b0000;
        end else if (up) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end
endmodule

