module top_module(
    HI,
    LO,
    VPWR,
    VGND,
    VPB,
    VNB
);output HI;
    output LO;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    wire HI_internal;
    wire LO_internal;

    assign HI = HI_internal;
    assign LO = LO_internal;

